<?php
require_once __DIR__.'/includes/functions.php';$page_title='Explore resources';$where=["r.status='approved'"];$params=[];
$q=trim($_GET['q']??'');$type=$_GET['type']??'';$dept=(int)($_GET['department_id']??0);$course=(int)($_GET['course_id']??0);$semester=(int)($_GET['semester_id']??0);
if($q!==''){$where[]="(r.title LIKE ? OR r.description LIKE ? OR s.name LIKE ? OR s.code LIKE ?)";$like="%$q%";array_push($params,$like,$like,$like,$like);}
if(in_array($type,['question_paper','syllabus','notes','assignment','presentation','other'],true)){$where[]="r.type=?";$params[]=$type;}
if($dept){$where[]="r.department_id=?";$params[]=$dept;}if($course){$where[]="r.course_id=?";$params[]=$course;}if($semester){$where[]="r.semester_id=?";$params[]=$semester;}
$sql="SELECT r.*,u.name uploader,s.name subject_name,s.code subject_code,d.name department_name FROM resources r JOIN users u ON u.id=r.uploaded_by LEFT JOIN subjects s ON s.id=r.subject_id LEFT JOIN departments d ON d.id=r.department_id WHERE ".implode(' AND ',$where)." ORDER BY r.created_at DESC LIMIT 100";
$s=$pdo->prepare($sql);$s->execute($params);$resources=$s->fetchAll();$departments=$pdo->query("SELECT id,name FROM departments ORDER BY name")->fetchAll();$courses=$pdo->query("SELECT id,name FROM courses ORDER BY name")->fetchAll();$semesters=$pdo->query("SELECT id,name FROM semesters")->fetchAll();require __DIR__.'/includes/header.php';?>
<section class="page-heading"><span class="eyebrow">THE ACADEMIC LIBRARY</span><h1>Explore resources</h1><p>Find question papers, syllabus documents, notes and more.</p></section>
<form class="filter-bar" method="get"><input name="q" value="<?= e($q) ?>" placeholder="Search title, subject or subject code..."><select name="type"><option value="">All resource types</option><?php foreach(['question_paper'=>'Question papers','syllabus'=>'Syllabus','notes'=>'Notes','assignment'=>'Assignments','presentation'=>'Presentations','other'=>'Other'] as $k=>$v): ?><option value="<?= $k ?>" <?= $type===$k?'selected':'' ?>><?= $v ?></option><?php endforeach; ?></select><select name="department_id"><option value="">All departments</option><?php foreach($departments as $d): ?><option value="<?= $d['id'] ?>" <?= $dept===$d['id']?'selected':'' ?>><?= e($d['name']) ?></option><?php endforeach; ?></select><select name="course_id"><option value="">All courses</option><?php foreach($courses as $c): ?><option value="<?= $c['id'] ?>" <?= $course===$c['id']?'selected':'' ?>><?= e($c['name']) ?></option><?php endforeach; ?></select><select name="semester_id"><option value="">All semesters</option><?php foreach($semesters as $x): ?><option value="<?= $x['id'] ?>" <?= $semester===$x['id']?'selected':'' ?>><?= e($x['name']) ?></option><?php endforeach; ?></select><button class="btn primary">Search</button></form>
<p class="result-count"><?= count($resources) ?> resource(s) found</p><div class="resource-grid"><?php foreach($resources as $r): ?><article class="resource-card"><div class="file-thumb"><?= strtoupper(e(pathinfo($r['original_name'],PATHINFO_EXTENSION))) ?></div><div class="resource-info"><span class="pill"><?= e(str_replace('_',' ',$r['type'])) ?></span><h3><?= e($r['title']) ?></h3><p><?= e($r['subject_code'] ? $r['subject_code'].' · '.$r['subject_name'] : ($r['department_name']??'University resource')) ?></p><small><?= e($r['uploader']) ?> · <?= e(date('d M Y',strtotime($r['created_at']))) ?></small><a class="card-link" href="<?= url('resource.php?id='.$r['id']) ?>">Preview & details →</a></div></article><?php endforeach; if(!$resources): ?><div class="empty">No resources match your search. Try changing the filters.</div><?php endif; ?></div>
<?php require __DIR__.'/includes/footer.php';?>